import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
number = data[1]

keypad = {
    '0': (1, 3),
    '1': (0, 0), '2': (1, 0), '3': (2, 0),
    '4': (0, 1), '5': (1, 1), '6': (2, 1),
    '7': (0, 2), '8': (1, 2), '9': (2, 2)
}

def direction(key1, key2):
    x1, y1 = keypad[key1]
    x2, y2 = keypad[key2]
    return (x2 - x1, y2 - y1)

finger_movements = [direction(number[i], number[i+1]) for i in range(n - 1)]

unique = True

for i in range(10**(n-1)):
    candidate = str(i).zfill(n)
    if candidate == number:
        continue
    candidate_movements = [direction(candidate[j], candidate[j+1]) for j in range(n - 1)]
    if candidate_movements == finger_movements:
        unique = False
        break

if unique:
    print("YES")
else:
    print("NO")

